import json, urllib.request, urllib.parse, os
import processing
from qgis.core import QgsVectorLayer, QgsCoordinateReferenceSystem

study = helpers.get_study_zone()
commune_name = study.get('name', '') if study else ''

if not commune_name:
    result['skipped'] = 'Nom de zone non trouve'
    result['success'] = True
else:
    try:
        # 1) Resoudre nom -> INSEE (gere Paris/Marseille/Lyon arrondissements)
        commune_info = helpers.search_commune(commune_name)
        if 'error' in commune_info:
            result['warning'] = 'Commune non trouvee : ' + commune_name + ' (' + commune_info['error'] + ')'
            result['success'] = True
        else:
            insee = commune_info.get('code', '')
            result['commune_nom'] = commune_info.get('nom', commune_name)
            result['commune_code'] = insee

            # 2) Fetch contour via INSEE direct (geo.api.gouv.fr supporte arrondissements en lookup par code)
            url = 'https://geo.api.gouv.fr/communes/' + urllib.parse.quote(insee) + '?fields=contour&geometry=contour&format=geojson'
            with urllib.request.urlopen(url, timeout=20) as resp:
                geojson_data = json.loads(resp.read().decode('utf-8'))
            # geo.api retourne soit un Feature soit une FeatureCollection selon endpoint
            if 'features' not in geojson_data:
                # Convertir Feature en FeatureCollection
                geojson_data = {'type': 'FeatureCollection', 'features': [geojson_data]}
            if not geojson_data.get('features'):
                result['warning'] = 'Contour absent pour INSEE ' + insee
                result['success'] = True
            else:
                tmp = '/tmp/commune_boundary.geojson'
                with open(tmp, 'w', encoding='utf-8') as f:
                    json.dump(geojson_data, f)

                commune_4326 = QgsVectorLayer(tmp, 'commune_tmp', 'ogr')
                if not commune_4326.isValid():
                    result['warning'] = 'GeoJSON commune invalide'
                    result['success'] = True
                else:
                    commune_4326.setCrs(QgsCoordinateReferenceSystem('EPSG:4326'))
                    commune_fixed = processing.run('native:fixgeometries', {
                        'INPUT': commune_4326, 'METHOD': 1, 'OUTPUT': 'memory:'
                    })['OUTPUT']
                    commune_2154 = processing.run('native:reprojectlayer', {
                        'INPUT': commune_fixed,
                        'TARGET_CRS': 'EPSG:2154',
                        'OUTPUT': 'memory:'
                    })['OUTPUT']
                    commune_2154.setName('Limite communale')
                    project.addMapLayer(commune_2154)
                    result['success'] = True
                    try: os.unlink(tmp)
                    except: pass
    except Exception as e:
        result['warning'] = 'Echec recuperation limite communale : ' + str(e)
        result['success'] = True

import processing
from qgis.core import QgsVectorLayer, QgsCoordinateReferenceSystem, QgsCoordinateTransform

def find_exact(name):
    return next((l for l in project.mapLayers().values()
                 if isinstance(l, QgsVectorLayer) and l.name() == name), None)

commune_2154 = find_exact('Limite communale')
if not commune_2154:
    result['warning'] = 'Limite communale absente (step precedent a echoue), skip expansion T1000'
    result['success'] = True
else:
    # Trouver la zone de crue la plus large (T1000 = crues extremes)
    def find_flood_zone(priorities):
        for pattern in priorities:
            l = next((l for l in project.mapLayers().values()
                      if isinstance(l, QgsVectorLayer)
                      and pattern in l.name().lower()
                      and 'hauteur' not in l.name().lower()
                      and l.geometryType() == 2), None)
            if l:
                return l
        return None

    flood_clip_zone = find_flood_zone(['t1000', 'treme', 't100', 'centennale', 't10', 'quente'])
    flood_dissolved = None

    if flood_clip_zone:
        flood_fixed = processing.run('native:fixgeometries', {
            'INPUT': flood_clip_zone, 'METHOD': 1, 'OUTPUT': 'memory:'
        })['OUTPUT']
        flood_dissolved = processing.run('native:dissolve', {
            'INPUT': flood_fixed, 'OUTPUT': 'memory:'
        })['OUTPUT']
        result['flood_clip_zone'] = flood_clip_zone.name()

        # Bbox de T1000 en EPSG:4326 pour redownload routes (couverture etendue)
        crs_4326 = QgsCoordinateReferenceSystem('EPSG:4326')
        tr_4326 = QgsCoordinateTransform(flood_clip_zone.crs(), crs_4326, project)
        t1000_ext = tr_4326.transformBoundingBox(flood_clip_zone.extent())
        t1000_bbox_4326 = [
            t1000_ext.xMinimum(), t1000_ext.yMinimum(),
            t1000_ext.xMaximum(), t1000_ext.yMaximum()
        ]
        result['t1000_bbox_4326'] = [round(v, 5) for v in t1000_bbox_4326]

        # Re-telecharger routes avec bbox T1000 (smart_load initial utilisait bbox commune,
        # les routes dans extension T1000 hors commune n'etaient pas telechargees).
        old_route = find_exact('Routes (BD TOPO)')
        if old_route:
            project.removeMapLayer(old_route.id())
        dl_route = helpers.download_wfs_ogr(
            'https://data.geopf.fr/wfs/ows',
            'BDTOPO_V3:troncon_de_route',
            bbox_4326=t1000_bbox_4326,
            name='Routes (BD TOPO)'
        )
        if 'error' in dl_route:
            result['route_redownload_warning'] = dl_route['error']
        else:
            result['routes_t1000_downloaded'] = dl_route.get('feature_count', '?')
            result['routes_cached'] = dl_route.get('cached', False)

    # Batiments: clip A LA COMMUNE UNIQUEMENT (PAS double clip a T1000).
    # Tous les batiments de la commune restent visibles ; la jointure spatiale
    # de l'etape 'analysis' marque ensuite ceux qui sont exposes vs hors zone.
    # Ceci corrige le bug PDF observe ou seul le bati intersectant T1000 etait rendu.
    bat = find_exact('B\u00e2timents (BD TOPO)')
    if bat:
        bat_count = bat.featureCount()
        bat_commune = processing.run('native:clip', {
            'INPUT': bat, 'OVERLAY': commune_2154, 'OUTPUT': 'memory:'
        })['OUTPUT']
        bat_commune.setName('B\u00e2timents (BD TOPO)')
        project.addMapLayer(bat_commune)
        project.removeMapLayer(bat.id())
        result['bat_avant'] = bat_count
        result['bat_apres'] = bat_commune.featureCount()

    # Routes: clip a T1000 (re-telechargees ci-dessus)
    route = find_exact('Routes (BD TOPO)')
    if route and flood_dissolved:
        route_count = route.featureCount()
        route_clip = processing.run('native:clip', {
            'INPUT': route, 'OVERLAY': flood_dissolved, 'OUTPUT': 'memory:'
        })['OUTPUT']
        route_clip.setName('Routes (BD TOPO)')
        project.addMapLayer(route_clip)
        project.removeMapLayer(route.id())
        result['route_avant'] = route_count
        result['route_apres'] = route_clip.featureCount()
    elif route:
        result['route_warning'] = 'Zone de crue non trouvee -- routes conservees sans clip'

    result['success'] = True

import processing
from qgis.core import QgsVectorLayer, QgsField, QgsFeatureRequest

def find_exact(name):
    return next((l for l in project.mapLayers().values()
                 if isinstance(l, QgsVectorLayer) and l.name() == name), None)

def find_kw(kw):
    return next((l for l in project.mapLayers().values()
                 if isinstance(l, QgsVectorLayer) and kw.lower() in l.name().lower()), None)

def fix(layer):
    return processing.run('native:fixgeometries', {'INPUT': layer, 'METHOD': 1, 'OUTPUT': 'memory:'})['OUTPUT']

def parse_ht(raw):
    if raw is None or str(raw) in ('', 'NULL', 'None'): return -1.0
    try:
        v = float(str(raw))
        return min(v, 5.0) if v < 9000 else 5.0
    except: return -1.0

# Couches source
bat_layer   = find_exact('Bâtiments (BD TOPO)')
route_layer = find_exact('Routes (BD TOPO)')

# Resoudre les couches hauteur par scenario (t1000 avant t100 avant t10 pour eviter substring match)
ht_layers = {}
for l in project.mapLayers().values():
    if not isinstance(l, QgsVectorLayer): continue
    n = l.name().lower()
    if 'hauteur' not in n: continue
    if 't1000' in n or 'extr' in n:       ht_layers['t1000'] = l
    elif 't100' in n or 'centennale' in n: ht_layers['t100']  = l
    elif 't10' in n or 'quente' in n:      ht_layers['t10']   = l
    else: ht_layers.setdefault('t100', l)

if 't100' not in ht_layers:
    result['warning'] = 'Hauteurs T100 non trouvees -- commune hors TRI Georisques'
    result['success'] = True
elif not bat_layer:
    result['error'] = 'Couche batiments manquante'
else:
    # Fixer geometries hauteur -- ISO_HT de Georisques peut avoir des self-intersections
    ht_fixed = {sc: fix(l) for sc, l in ht_layers.items()}
    result['scenarios_hauteur'] = list(ht_fixed.keys())

    # Batiments : jointure multi-scenarios
    # METHOD=1 (premier match) vs METHOD=2 (plus grand overlap) -- evite le calcul d'aire, ~3x plus rapide
    # ISO_HT sont des zones disjointes (classes de profondeur), donc premier match = bon match
    has_routes = route_layer is not None
    bat_work = bat_layer
    for sc, ht in ht_fixed.items():
        bat_work = processing.run('native:joinattributesbylocation', {
            'INPUT': bat_work, 'JOIN': ht,
            'PREDICATE': [0], 'JOIN_FIELDS': ['ht_min', 'ht_max'],
            'METHOD': 1, 'DISCARD_NONMATCHING': False,
            'PREFIX': sc + '_', 'OUTPUT': 'memory:'
        })['OUTPUT']
    bat_work.setName('Bâtiments')
    bat_work = project.addMapLayer(bat_work)
    orig_bat = find_exact('Bâtiments (BD TOPO)')
    if orig_bat: project.removeMapLayer(orig_bat.id())

    # Routes : jointure multi-scenarios + ht_num Double
    if has_routes:
        route_work = route_layer
        for sc, ht in ht_fixed.items():
            route_work = processing.run('native:joinattributesbylocation', {
                'INPUT': route_work, 'JOIN': ht,
                'PREDICATE': [0], 'JOIN_FIELDS': ['ht_min', 'ht_max'],
                'METHOD': 1, 'DISCARD_NONMATCHING': False,
                'PREFIX': sc + '_', 'OUTPUT': 'memory:'
            })['OUTPUT']
        # ht_num_tXX via fieldcalculator C++ -- rapide sur 35k routes
        for sc in list(ht_fixed.keys()):
            fn = sc + '_ht_max'
            if route_work.fields().indexOf(fn) >= 0:
                expr = 'CASE WHEN "%s" IS NULL THEN -1.0 WHEN to_real("%s") >= 9000 THEN 5.0 ELSE minimum(to_real("%s"), 5.0) END' % (fn, fn, fn)
                route_work = processing.run('native:fieldcalculator', {
                    'INPUT': route_work, 'FIELD_NAME': 'ht_num_' + sc,
                    'FIELD_TYPE': 0, 'FORMULA': expr, 'OUTPUT': 'memory:'
                })['OUTPUT']
        # Alias ht_num = t100 (retrocompat style QGIS)
        if route_work.fields().indexOf('t100_ht_max') >= 0:
            expr = 'CASE WHEN "t100_ht_max" IS NULL THEN -1.0 WHEN to_real("t100_ht_max") >= 9000 THEN 5.0 ELSE minimum(to_real("t100_ht_max"), 5.0) END'
            route_work = processing.run('native:fieldcalculator', {
                'INPUT': route_work, 'FIELD_NAME': 'ht_num',
                'FIELD_TYPE': 0, 'FORMULA': expr, 'OUTPUT': 'memory:'
            })['OUTPUT']
        route_work.setName('Routes')
        route_work = project.addMapLayer(route_work)
        orig_route = find_exact('Routes (BD TOPO)')
        if orig_route: project.removeMapLayer(orig_route.id())

    # Stats T100 -- NoGeometry + attribut seul pour perf sur 100k features
    total_bat = bat_work.featureCount()
    idx = bat_work.fields().indexOf('t100_ht_max')
    if idx < 0: idx = bat_work.fields().indexOf('ht_max')
    depth = {'< 0.5m': 0, '0.5-1m': 0, '1-2m': 0, '> 2m': 0, 'hors_zone': 0}
    req = QgsFeatureRequest().setFlags(QgsFeatureRequest.NoGeometry).setSubsetOfAttributes([idx])
    for f in bat_work.getFeatures(req):
        v = parse_ht(f.attribute(idx))
        if v < 0:        depth['hors_zone'] += 1
        elif v <= 0.5:   depth['< 0.5m']   += 1
        elif v <= 1.0:   depth['0.5-1m']   += 1
        elif v <= 2.0:   depth['1-2m']     += 1
        else:            depth['> 2m']     += 1
    exposed = total_bat - depth['hors_zone']
    result['stats'] = {
        'total_batiments': total_bat,
        'exposes_T100': exposed,
        'taux_exposition_pct': round(exposed / max(total_bat, 1) * 100, 1),
        'par_classe_profondeur': depth
    }
    if has_routes:
        ridx = route_work.fields().indexOf('ht_num')
        rs = {'hors_zone': 0, 'carrossable': 0, 'difficile': 0, 'impraticable': 0, 'bloquee': 0}
        req_r = QgsFeatureRequest().setFlags(QgsFeatureRequest.NoGeometry).setSubsetOfAttributes([ridx] if ridx >= 0 else [])
        for f in route_work.getFeatures(req_r):
            v = f.attribute(ridx) if ridx >= 0 else None
            if v is None or v < 0:  rs['hors_zone']    += 1
            elif v <= 0.5:           rs['carrossable']  += 1
            elif v <= 1.0:           rs['difficile']    += 1
            elif v <= 2.0:           rs['impraticable'] += 1
            else:                    rs['bloquee']      += 1
        result['stats']['routes'] = rs
    result['success'] = True

from qgis.core import (QgsFillSymbol, QgsSingleSymbolRenderer, QgsGraduatedSymbolRenderer,
                        QgsRendererRange, QgsVectorLayer, QgsCoordinateTransform,
                        QgsLineSymbol, QgsMarkerSymbol, QgsRuleBasedRenderer,
                        QgsCategorizedSymbolRenderer, QgsRendererCategory, QgsMapLayer)

def find_kw(kw):
    return [l for l in project.mapLayers().values()
            if isinstance(l, QgsVectorLayer) and kw.lower() in l.name().lower()]

def find_exact(name):
    return next((l for l in project.mapLayers().values()
                 if isinstance(l, QgsVectorLayer) and l.name() == name), None)

# ── 0. Zoom sur la zone de travail au debut ──
ref_zones = find_kw('(T1000)') or find_kw('treme') or find_kw('(T100)') or find_kw('centennale')
if ref_zones:
    canvas = iface.mapCanvas()
    tr = QgsCoordinateTransform(ref_zones[0].crs(), project.crs(), project)
    ext = tr.transformBoundingBox(ref_zones[0].extent())
    canvas.setExtent(ext)
    canvas.zoomByFactor(1.1)

# ── 1. Zones inondables — bleu gradue ──
zone_styles = [
    ('(T1000)', '150,200,255,40',  '80,130,200,60',  0.15),
    ('(T100)',  '90,140,230,70',   '40,80,190,90',   0.2),
    ('(T10)',   '30,70,180,90',    '15,45,140,110',  0.3),
]
for pattern, fill, outline, width in zone_styles:
    for l in find_kw(pattern):
        if l.geometryType() == 2 and 'timent' not in l.name() and 'hauteur' not in l.name():
            sym = QgsFillSymbol.createSimple({'color': fill, 'outline_color': outline, 'outline_width': str(width)})
            l.setRenderer(QgsSingleSymbolRenderer(sym))
            l.triggerRepaint()

# ── 2. Hauteurs d'eau — style (reste en projet mais sera masquee) ──
for l in find_kw('hauteur'):
    depth_colors = [
        (0,   0.5,  '180,220,255,80',  '< 0.5m'),
        (0.5, 1.0,  '90,160,230,110',  '0.5-1m'),
        (1.0, 2.0,  '50,100,200,140',  '1-2m'),
        (2.0, 5.0,  '20,50,150,170',   '> 2m'),
    ]
    rngs = []
    for lo, hi, color, label in depth_colors:
        sym = QgsFillSymbol.createSimple({'color': color, 'outline_color': '30,60,150,80', 'outline_width': '0.1'})
        rngs.append(QgsRendererRange(lo, hi, sym, label))
    l.setRenderer(QgsGraduatedSymbolRenderer('ht_max', rngs))
    l.triggerRepaint()

# ── 3. Batiments — regles COALESCE tous scenarios ──
bat = find_exact('B\u00e2timents')
if bat:
    root_rule = QgsRuleBasedRenderer.Rule(None)
    ht_scenarios = [sc + '_ht_max' for sc in ['t1000', 't100', 't10'] if bat.fields().indexOf(sc + '_ht_max') >= 0]
    if ht_scenarios:
        parts = ', '.join('to_real("%s")' % f for f in ht_scenarios)
        ht_expr = 'COALESCE(%s)' % parts
    elif bat.fields().indexOf('ht_max') >= 0:
        ht_expr = 'to_real("ht_max")'
    else:
        ht_expr = '-1'
    bat_rules = [
        ('(%s) IS NULL OR (%s) < 0' % (ht_expr, ht_expr), '200,200,200,80', '150,150,150,60', '0.1', 'Hors zone'),
        ('(%s) <= 0.5' % ht_expr,                          '255,240,100,220', '200,180,30,180', '0.25', '< 0.5m'),
        ('(%s) > 0.5 AND (%s) <= 1.0' % (ht_expr, ht_expr), '255,165,30,225', '200,110,10,185', '0.3',  '0.5-1m'),
        ('(%s) > 1.0 AND (%s) <= 2.0' % (ht_expr, ht_expr), '255,110,30,230', '180,65,10,190',  '0.35', '1-2m'),
        ('(%s) > 2.0' % ht_expr,                            '210,25,25,240',  '140,10,10,200',  '0.4',  '> 2m'),
    ]
    for expr, fill, outline, width, label in bat_rules:
        sym = QgsFillSymbol.createSimple({'color': fill, 'outline_color': outline, 'outline_width': width})
        rule = QgsRuleBasedRenderer.Rule(sym)
        rule.setFilterExpression(expr)
        rule.setLabel(label)
        root_rule.appendChild(rule)
    bat.setRenderer(QgsRuleBasedRenderer(root_rule))
    bat.triggerRepaint()

# ── 4. Routes — regles ht_num ──
route = find_exact('Routes')
if route:
    root_rule = QgsRuleBasedRenderer.Rule(None)
    rt_rules = [
        ('ht_num < 0',                     '#888888', '0.26', 'Hors zone'),
        ('ht_num >= 0 AND ht_num <= 0.5',  '#1ed241', '0.4',  '< 0.5m — Carrossable'),
        ('ht_num > 0.5 AND ht_num <= 1.0', '#f0c800', '0.4',  '0.5-1m — Difficile'),
        ('ht_num > 1.0 AND ht_num <= 2.0', '#ff5a00', '0.4',  '1-2m — Impraticable'),
        ('ht_num > 2.0',                   '#d21414', '0.4',  '> 2m — Bloquee'),
    ]
    for expr, color, width, label in rt_rules:
        sym = QgsLineSymbol.createSimple({'color': color, 'width': width})
        rule = QgsRuleBasedRenderer.Rule(sym)
        rule.setFilterExpression(expr)
        rule.setLabel(label)
        root_rule.appendChild(rule)
    route.setRenderer(QgsRuleBasedRenderer(root_rule))
    route.triggerRepaint()

# ── 5. Enjeux sensibles — icones par categorie ──
sensibles_layers = find_kw('sensible') + find_kw('enjeux')
for l in sensibles_layers:
    cat_field = None
    for fname in ['typ_ets', 'categorie', 'nature', 'type']:
        if l.fields().indexOf(fname) >= 0:
            cat_field = fname
            break
    def cat_style(val):
        v = val.upper()
        if any(k in v for k in ['SANTE', 'HOPITAL', 'MEDIC', 'CLINIC', 'CHU', 'CHR', 'URGENCE']):
            return '#e63946', 'cross', '5.0', 'Sante / Hopital'
        elif any(k in v for k in ['EDUC', 'ECOLE', 'UNIVERSI', 'SCOLAIRE', 'LYCEE', 'COLLEGE']):
            return '#2196F3', 'rectangle', '4.5', 'Enseignement'
        elif any(k in v for k in ['SECOUR', 'POMPIER', 'GENDARME', 'POLICE', 'SAPEUR']):
            return '#ff9800', 'star', '5.0', 'Secours / Securite'
        elif any(k in v for k in ['ERP', 'PUBLIC', 'ACCUEIL', 'MAIRIE', 'ADMIN']):
            return '#9c27b0', 'diamond', '4.5', 'ERP / Service public'
        else:
            return '#607d8b', 'circle', '4.0', val[:40]
    if cat_field:
        unique_vals = sorted(set(
            str(f[cat_field]) for f in l.getFeatures()
            if f[cat_field] is not None and str(f[cat_field]) not in ('', 'NULL', 'None')
        ))
        cats = []
        for val in unique_vals:
            color, shape, size, label = cat_style(val)
            sym = QgsMarkerSymbol.createSimple({
                'name': shape, 'color': color,
                'outline_color': '#ffffff', 'outline_width': '0.5', 'size': size
            })
            cats.append(QgsRendererCategory(val, sym, label))
        if cats:
            l.setRenderer(QgsCategorizedSymbolRenderer(cat_field, cats))
        else:
            sym = QgsMarkerSymbol.createSimple({'name': 'triangle', 'color': '255,140,0,230', 'outline_color': '180,80,0', 'size': '4'})
            l.setRenderer(QgsSingleSymbolRenderer(sym))
    else:
        sym = QgsMarkerSymbol.createSimple({'name': 'triangle', 'color': '255,140,0,230', 'outline_color': '180,80,0', 'size': '4'})
        l.setRenderer(QgsSingleSymbolRenderer(sym))
    l.triggerRepaint()

# ── 6. Limite communale — gris pointille ──
commune_l = find_exact('Limite communale')
if commune_l:
    sym = QgsFillSymbol.createSimple({
        'color': '0,0,0,0',
        'outline_color': '100,100,100,200',
        'outline_width': '0.8',
        'outline_style': 'dash'
    })
    commune_l.setRenderer(QgsSingleSymbolRenderer(sym))
    commune_l.triggerRepaint()

# ── 7. Ordre de rendu et visibilite ──
# setCustomLayerOrder QGIS : index 0 = TOPMOST (dessine en dernier / DEVANT),
# index -1 = BOTTOMMOST (dessine en premier / DERRIERE).
# Donc on construit la liste top->bottom : sensibles en premier (DEVANT),
# raster basemap en DERNIER (DERRIERE).
root = project.layerTreeRoot()
layers_ordered = []   # top -> bottom (DEVANT -> DERRIERE)
seen_ids = set()

def add_l(l, visible=True):
    if l and l.id() not in seen_ids:
        seen_ids.add(l.id())
        layers_ordered.append((l, visible))

for l in (find_kw('sensible') + find_kw('enjeux')):
    add_l(l, True)
add_l(find_exact('B\u00e2timents'), True)
add_l(find_exact('Routes'), True)
for kw in ['(T10)', '(T100)', '(T1000)']:
    for l in find_kw(kw):
        if l.geometryType() == 2 and 'timent' not in l.name() and 'hauteur' not in l.name():
            add_l(l, True)
for l in find_kw('hauteur'):
    add_l(l, False)   # masquees mais restent dans le projet
add_l(commune_l, True)
# Raster basemap EN DERNIER (= rendu en premier = ARRIERE-PLAN). Fix bug observe
# en E2E ou setCustomLayerOrder(reversed(...)) mettait basemap raster AU-DESSUS.
for l in project.mapLayers().values():
    if not isinstance(l, QgsVectorLayer) and l.id() not in seen_ids:
        seen_ids.add(l.id())
        layers_ordered.append((l, True))

# setCustomLayerOrder attend la liste dans l'ordre top->bottom (premier=devant).
# Notre layers_ordered est deja dans le bon ordre, on passe SANS reversed.
render_layers = [l for l, v in layers_ordered]
root.setCustomLayerOrder(render_layers)
root.setHasCustomLayerOrder(True)

# Visibilite dans le panneau couches
for layer, visible in layers_ordered:
    node = root.findLayer(layer.id())
    if node:
        node.setItemVisibilityChecked(visible)

result['success'] = True
